ALTER TABLE "finance"."debt_settlement" DROP CONSTRAINT "ck_settlement_amounts";--> statement-breakpoint
ALTER TABLE "finance"."debt_settlement" DROP CONSTRAINT "ck_settlement_confirmation";--> statement-breakpoint
ALTER TABLE "finance"."settlement_component" DROP CONSTRAINT "ck_settlement_rounding_treatment";--> statement-breakpoint
ALTER TABLE "finance"."settlement_component" DROP CONSTRAINT "ck_settlement_component_shape";--> statement-breakpoint
ALTER TABLE "finance"."debt_settlement" ADD CONSTRAINT "ck_settlement_amounts" CHECK ("finance"."debt_settlement"."confirmed_payoff_minor">=0 AND "finance"."debt_settlement"."confirmed_payoff_minor"<=100000000000 AND "finance"."debt_settlement"."actual_cash_paid_minor"<=100000000000 AND "finance"."debt_settlement"."actual_cash_paid_minor">="finance"."debt_settlement"."confirmed_payoff_minor" AND "finance"."debt_settlement"."resolved_unapplied_minor">=0);--> statement-breakpoint
ALTER TABLE "finance"."debt_settlement" ADD CONSTRAINT "ck_settlement_confirmation" CHECK ("finance"."debt_settlement"."confirmation_source" IN ('user','provider') AND length(trim("finance"."debt_settlement"."confirmation_note"))>0 AND length(trim("finance"."debt_settlement"."reason"))>0 AND ("finance"."debt_settlement"."resolved_unapplied_minor"=0 OR COALESCE(length(trim("finance"."debt_settlement"."unapplied_resolution_note")),0)>0));--> statement-breakpoint
ALTER TABLE "finance"."settlement_component" ADD CONSTRAINT "ck_settlement_rounding_treatment" CHECK (("finance"."settlement_component"."component_kind"='rounding_correction' AND "finance"."settlement_component"."rounding_treatment" IS NOT NULL AND "finance"."settlement_component"."rounding_treatment" IN ('recognized_charge','recognized_waiver')) OR ("finance"."settlement_component"."component_kind"<>'rounding_correction' AND "finance"."settlement_component"."rounding_treatment" IS NULL));--> statement-breakpoint
ALTER TABLE "finance"."settlement_component" ADD CONSTRAINT "ck_settlement_component_shape" CHECK (("finance"."settlement_component"."component_kind"='avoided_future_charge' AND "finance"."settlement_component"."effect_posting_id" IS NULL AND "finance"."settlement_component"."counter_posting_id" IS NULL AND "finance"."settlement_component"."recognized_source_posting_id" IS NULL AND "finance"."settlement_component"."liability_component" IS NULL AND NOT "finance"."settlement_component"."unknown_opening") OR ("finance"."settlement_component"."component_kind"<>'avoided_future_charge' AND "finance"."settlement_component"."effect_posting_id" IS NOT NULL AND "finance"."settlement_component"."counter_posting_id" IS NOT NULL AND "finance"."settlement_component"."liability_component" IS NOT NULL AND "finance"."settlement_component"."liability_component" IN ('principal','interest','fee','penalty','unclassified')));